gJl(){return"\u041d\u0430\u0436\u043c\u0438\u0442\u0435 \u0438 \u0443\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0439\u0442\u0435 \u0432\u0438\u0434\u0435\u043e \u0434\u043b\u044f \u043f\u0435\u0440\u0435\u043c\u043e\u0442\u043a\u0438 \u0432\u043f\u0435\u0440\u0451\u0434. \u041f\u0440\u043e\u0432\u0435\u0434\u0438\u0442\u0435 \u0432\u0432\u0435\u0440\u0445, \u043d\u0435 \u043e\u0442\u043f\u0443\u0441\u043a\u0430\u044f, \u0447\u0442\u043e\u0431\u044b \u0443\u0441\u043a\u043e\u0440\u0438\u0442\u044c \u0435\u0449\u0451 \u0431\u043e\u043b\u044c\u0448\u0435."},
